#!/usr/bin/env python3
"""Validates SPDX and CycloneDX SBOMs generated by @supply_chain_tools."""

import argparse
import json
import sys


def validate_spdx(path):
    print(f"Validating SPDX SBOM: {path}")
    with open(path, "r", encoding="utf-8") as f:
        doc = json.load(f)

    assert doc.get("spdxVersion") == "SPDX-2.3", f"Unexpected spdxVersion: {doc.get('spdxVersion')}"
    packages = doc.get("packages", [])
    print(f"SPDX: found {len(packages)} packages.")
    assert len(packages) >= 50, f"Expected at least 50 packages in SPDX, found {len(packages)}"

    pkg_by_name = {p["name"]: p for p in packages}
    expected_pkgs = ["curl", "bash", "glibc", "openssl-libs", "ca-certificates", "filesystem"]
    for name in expected_pkgs:
        assert name in pkg_by_name, f"Expected package '{name}' not found in SPDX"
        p = pkg_by_name[name]
        ext_refs = p.get("externalRefs", [])
        purl_refs = [r for r in ext_refs if r.get("referenceType") == "purl"]
        assert len(purl_refs) >= 1, f"Missing PURL for {name}"
        purl = purl_refs[0].get("referenceLocator", "")
        assert purl.startswith(f"pkg:rpm/oracle/{name}@"), f"PURL {purl} invalid prefix"
        assert "distro=ol10" in purl, f"PURL {purl} missing distro=ol10"

    print(f"SPDX validation passed for {path}.")


def validate_cyclonedx(path):
    print(f"Validating CycloneDX SBOM: {path}")
    with open(path, "r", encoding="utf-8") as f:
        doc = json.load(f)

    assert doc.get("bomFormat") == "CycloneDX", f"Unexpected bomFormat: {doc.get('bomFormat')}"
    components = doc.get("components", [])
    print(f"CycloneDX: found {len(components)} components.")
    assert len(components) >= 50, f"Expected at least 50 components in CycloneDX, found {len(components)}"

    purls = {c.get("purl"): c for c in components if c.get("purl")}
    expected_pkgs = ["curl", "bash", "glibc", "openssl-libs", "ca-certificates", "filesystem"]
    for name in expected_pkgs:
        matching = [p for p in purls if p.startswith(f"pkg:rpm/oracle/{name}@")]
        assert len(matching) >= 1, f"Expected CycloneDX component for {name} with PURL"
        assert "distro=ol10" in matching[0], f"CycloneDX PURL {matching[0]} missing distro=ol10"

    print(f"CycloneDX validation passed for {path}.")


def main():
    parser = argparse.ArgumentParser(description="Validate SPDX and CycloneDX SBOMs")
    parser.add_argument("--spdx", nargs="*", default=[], help="SPDX SBOM files to validate")
    parser.add_argument("--cyclonedx", nargs="*", default=[], help="CycloneDX SBOM files to validate")
    args = parser.parse_args()

    for p in args.spdx:
        validate_spdx(p)
    for p in args.cyclonedx:
        validate_cyclonedx(p)


if __name__ == "__main__":
    main()
